const body = $json.body || {};
let messageText = '';
let senderPhone = '';

if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value?.messages) {
  const messageObj = body.entry[0].changes[0].value.messages[0];
  messageText = messageObj.text?.body || '';
  senderPhone = messageObj.from || '';
} else {
  messageText = body.message || body.text || 'Hola';
  senderPhone = body.phone || body.from || 'test_user';
}

return { text: messageText, phone: senderPhone };

let raw = $json.text \vert{}\vert{}$json.output || '{}';
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { intencion: 'otro', termino_busqueda: null, categoria: null };
}

return {
  ...parsed,
  phone: $('Extraer Datos').first().json.phone
};

const items = $input.all();
const phone =$('Parsear Clasificacion').first().json.phone;
let msg = '';

if (items.length > 0 && items[0].json && items[0].json.id) {
  const row = items[0].json;
  if (row.estado === 'activo') {
    msg = `🛡️ *Verifik Shield - Certificado Verificado*\n\n` +
          `Comercio: *${row.tienda}*\n` +
          `Nivel de Confianza: Nivel ${row.nivel_verificacion || 1} ⭐\n` +
          `RIF: ${row.rif || 'N/A'}\n\n` +
          `🔗 Revisa el certificado oficial aquí:\n${row.url || 'Sin enlace disponible'}`;
  } else {
    msg = `⚠️ El comercio *${row.tienda}* está registrado pero su estatus no se encuentra activo actualmente.`;
  }
} else {
  msg = `❌ *Comercio no verificado en Verifik Shield.*\n\nNo encontramos registros activos para esa consulta. Te recomendamos operar con precaución o solicitarle que valide su certificación con nosotros.`;
}

return { reply: msg, phone };

const items = $input.all();
const phone =$('Parsear Clasificacion').first().json.phone;
let msg = '';

if (items.length > 0 && items[0].json && items[0].json.id) {
  msg = `🌟 *Comercios Recomendados por Verifik Shield*\n\n`;
  items.forEach((item, index) => {
    const row = item.json;
    msg += `${index + 1}. *${row.tienda}* (Nivel ${row.nivel_verificacion})\n` +
           `📂 Categoría: ${row.categoria}\n` +
           `🔗 Certificado: ${row.url}\n\n`;
  });
} else {
  msg = `ℹ️ Aún no contamos con comercios certificados activos en esa categoría específica.`;
}

return { reply: msg, phone };

